/* ==================================================
   BLACK EDITORIAL · ARCHIVE SYSTEM
   黑白档案馆 · HTML 配套 CSS
================================================== */

/* 01. 全局基础 */
.file-wrap,
.file-wrap * {
  box-sizing: border-box;
}

.file-wrap {
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  color: #171717;
  background: #fff;
  border: 1px solid #171717;
  border-radius: 0 !important;
  font-family: "Noto Serif SC", "Songti SC", serif;
}

/* 02. 顶部档案 */
.file-top {
  padding: 22px 19px 20px;
  background: #fff;
  border-bottom: 1px solid #171717;
}

.file-top::before {
  content: "ARCHIVE / PRIVATE RECORD";
  display: block;
  margin-bottom: 18px;
  color: #aaa;
  font-family: Arial, sans-serif;
  font-size: 9px;
  letter-spacing: 2.5px;
}

.file-tag {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  max-width: 100%;
  padding: 6px 9px;
  margin: 0 0 12px;
  color: #171717;
  background: #fff;
  border: 1px solid #222;
  border-radius: 0 !important;
  font-family: Arial, "Noto Serif SC", serif;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
}

.file-tag span {
  padding-left: 8px;
  border-left: 1px solid #bbb;
  font-family: "Noto Serif SC", serif;
  font-weight: 400;
}

.file-time {
  padding: 8px 0 14px;
  margin-bottom: 16px;
  color: #777;
  border-bottom: 1px dashed #ccc;
  font-family: Arial, sans-serif;
  font-size: 12px;
  line-height: 1.8;
  text-align: center;
}

.file-story,
.file-text {
  color: #3b3b3b;
  font-size: 13px;
  line-height: 1.95;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

/* 03. 横向分页 */
.file-slider-box {
  display: block;
  width: 100%;
  height: 520px;
  max-height: 68vh;
  min-height: 320px;
  overflow-x: auto;
  overflow-y: hidden;
  white-space: nowrap;
  font-size: 0;
  background: #fff;
  border-bottom: 1px solid #222;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}

.file-slider-box::-webkit-scrollbar {
  display: none;
}

/* 04. 单页 */
.file-page {
  display: inline-block;
  width: 100%;
  height: 100%;
  padding: 19px;
  overflow-x: hidden;
  overflow-y: auto;
  vertical-align: top;
  white-space: normal;
  font-size: 13px;
  background: #fff;
  scroll-snap-align: start;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.file-page::-webkit-scrollbar {
  display: none;
}

/* 05. 普通内容 */
.file-text {
  margin-bottom: 17px;
}

.block-box {
  padding: 14px;
  margin-bottom: 15px;
  color: #333;
  background: #fafafa;
  border: 1px solid #dedede;
  border-radius: 0 !important;
}

.mind-box {
  padding: 16px 10px;
  margin: 8px 0 19px;
  color: #777;
  background: #fafafa;
  border-top: 1px solid #ddd;
  border-bottom: 1px solid #ddd;
  font-size: 12px;
  line-height: 1.9;
  text-align: center;
  overflow-wrap: anywhere;
}

/* 06. 私聊 / 群聊：保留圆角 */
.chat-flow {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 10px 0;
}

.chat-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: 100%;
}

.chat-name {
  color: #999;
  font-family: Arial, sans-serif;
  font-size: 10px;
}

.chat-bubble {
  max-width: 85%;
  padding: 10px 14px;
  color: #333;
  background: #fff;
  border: 1px solid #222;
  font-size: 13px;
  line-height: 1.8;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.chat-row.left {
  align-items: flex-start;
}

.chat-row.left .chat-name {
  margin-left: 4px;
}

.chat-row.left .chat-bubble {
  border-radius: 0 12px 12px 12px;
}

.chat-row.right {
  align-items: flex-end;
}

.chat-row.right .chat-name {
  margin-right: 4px;
}

.chat-row.right .chat-bubble {
  border-radius: 12px 0 12px 12px;
}

/* 07. 论坛 */
#forum-box {
  width: 100%;
}

.forum-item {
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
  border: 1px solid #ddd;
  border-radius: 0 !important;
}

.forum-item summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 12px;
  background: #fafafa;
  cursor: pointer;
  list-style: none;
}

.forum-item summary::-webkit-details-marker {
  display: none;
}

.forum-title {
  flex: 1;
  min-width: 0;
  color: #222;
  font-size: 13px;
  font-weight: bold;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.forum-meta {
  flex-shrink: 0;
  color: #999;
  font-size: 10px;
}

.forum-content {
  padding: 14px;
  color: #444;
  border-top: 1px dashed #ddd;
  font-size: 12px;
  line-height: 1.8;
  overflow-wrap: anywhere;
}

.forum-lz {
  margin-bottom: 12px;
  font-weight: bold;
}

.forum-reply {
  padding: 10px 12px;
  margin-top: 8px;
  background: #fafafa;
  border-left: 2px solid #bbb;
  font-size: 12px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}

/* 08. 热搜 */
#trending-box {
  padding: 0 5px;
}

.hot-item {
  background: #fff;
  border-bottom: 1px dashed #ddd;
}

.hot-item:last-child {
  border-bottom: none;
}

.hot-item summary {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 14px 4px;
  cursor: pointer;
  list-style: none;
}

.hot-item summary::-webkit-details-marker {
  display: none;
}

.hot-rank {
  flex: 0 0 23px;
  color: #999;
  font-family: Arial, sans-serif;
  font-size: 15px;
  font-weight: bold;
  line-height: 1.5;
  text-align: center;
}

.hot-rank.top1 {
  color: #c63c3c;
}

.hot-rank.top2 {
  color: #a66a32;
}

.hot-rank.top3 {
  color: #a38c38;
}

.hot-title {
  flex: 1;
  min-width: 0;
  color: #222;
  font-size: 13px;
  font-weight: bold;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.hot-stats {
  display: flex;
  flex-shrink: 0;
  flex-direction: column;
  align-items: flex-end;
  margin-left: 4px;
  color: #999;
  font-size: 10px;
  line-height: 1.6;
}

.hot-detail {
  padding: 12px 12px 12px 30px;
  color: #555;
  background: #fafafa;
  border-top: 1px dashed #ddd;
  font-size: 12px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}

.hot-detail b {
  color: #222;
}

/* 09. 底部 */
.file-bottom {
  padding: 19px;
  color: #222;
  background: #fff;
  border-top: 1px solid #171717;
}

.file-end-title,
.file-memory-title {
  color: #222;
  font-size: 12px;
  font-weight: bold;
}

.file-end-text {
  padding: 8px 0 14px;
  color: #444;
  font-size: 13px;
  line-height: 1.9;
  text-align: right;
  overflow-wrap: anywhere;
}

.file-memory {
  padding: 13px;
  background: #fff;
  border: 1px solid #222;
  border-radius: 0 !important;
}

.file-memory-text {
  margin-top: 7px;
  color: #666;
  font-size: 12px;
  line-height: 1.9;
  overflow-wrap: anywhere;
}

/* 10. 系统提示 */
.sys-alert {
  padding: 13px;
  margin-top: 18px;
  color: #eee;
  background: #111;
  border: 1px solid #9e3434;
  border-left: 3px solid #9e3434;
  border-radius: 0 !important;
  box-shadow: 0 0 5px rgba(158,52,52,.12);
}

.sys-alert .file-tag {
  padding: 4px 7px;
  margin-bottom: 9px;
  color: #eee;
  background: #222;
  border-color: #9e3434;
  font-size: 9px;
  line-height: 1.4;
}

.sys-alert .file-tag span {
  border-color: #777;
  font-size: 10px;
}

.sys-alert-text {
  color: #ddd;
  font-size: 11px;
  line-height: 1.75;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

/* 11. 好感度 */
.favor-bar-bg {
  height: 7px;
  margin-top: 9px;
  overflow: hidden;
  background: #eee;
  border: 1px solid #ccc;
  border-radius: 0 !important;
}

.favor-bar-fill {
  width: {{favor}}%;
  height: 100%;
  background: #171717;
}

/* 12. 移动端 */
@media (max-width: 480px) {
  .file-top {
    padding: 19px 16px;
  }

  .file-page {
    padding: 16px;
  }

  .file-slider-box {
    height: 500px;
    max-height: 65vh;
  }

  .chat-bubble {
    max-width: 90%;
  }

  .file-bottom {
    padding: 16px;
  }
}

/* ==================================================
   SYSTEM PANEL · 操作按钮
   不改档案馆 HTML 的视觉
================================================== */

/* 面板变量 */
.xs-panel {
  --xs-bg: #fff;
  --xs-tile-bg: #fff;
  --xs-text: #171717;
  --xs-muted: #888;
  --xs-accent: #171717;
  --xs-border: #222;
  --xs-cap: #171717;
  --xs-action-bg: #fff;
  --xs-done-bg: #fff;
}

/* 历史 / 偏好 / 重ROLL */
.xs-panel .xs-action {
  color: #171717 !important;
  background: #fff !important;
  border: 1px solid #222 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 删除 */
.xs-panel .xs-delete,
.xs-panel .xs-remove,
.xs-panel button[class*="delete"],
.xs-panel button[class*="remove"] {
  color: #171717 !important;
  background: #fff !important;
  border: 1px solid #222 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* 右上角关闭 */
.xs-panel .xs-cap-x {
  display: flex !important;
  width: 36px !important;
  height: 36px !important;
  align-items: center !important;
  justify-content: center !important;
  color: #171717 !important;
  background: #fff !important;
  border: 1px solid #222 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* 底部关闭 */
.xs-panel .xs-done {
  padding: 12px 18px !important;
  color: #171717 !important;
  background: #fff !important;
  border: 1px solid #222 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* 悬停 */
.xs-panel .xs-action:hover,
.xs-panel .xs-done:hover,
.xs-panel .xs-delete:hover,
.xs-panel .xs-remove:hover {
  color: #fff !important;
  background: #171717 !important;
  border-color: #171717 !important;
}

/* 按钮内部 */
.xs-panel .xs-action *,
.xs-panel .xs-done *,
.xs-panel .xs-cap-x *,
.xs-panel .xs-delete *,
.xs-panel .xs-remove * {
  border-radius: 0 !important;
  box-shadow: none !important;
}
/* 强制一句话居中，消除代码缩进带来的空格偏移 */
.file-page .file-text[style*="text-align:center"],
.file-page .file-text[style*="text-align: center"] {
  text-align: center !important;
  white-space: normal !important; /* 核心：忽略代码里的回车和空格 */
  text-indent: 0 !important;
  padding: 0 !important;
}
